package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateProof {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ProofRequest request, Out<ProofInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        body.set(new ProofInput(request == null ? null : request.user()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Raises the claim's proofs count by one; refused for a SETTLED or VOID claim, or when another user moved it on first. */
public class ApplyProof {
    public void apply(@Val Claim claim, ClaimStore store) throws InvalidSheetException {
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID || !store.addProof(claim)) {
            throw new InvalidSheetException("A proof cannot be added to a " + claim.getStatus() + " claim");
        }
    }
}
package net.officefloor.hq.app.claim;

/** A validated proof: who adds it. */
public record ProofInput(String user) {
}
package net.officefloor.hq.app.claim;

/** Body of a claim's proof, as sent: who adds it. */
public record ProofRequest(String user) {
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;

/** Refuses settling an OPEN claim, or approving a PENDING one, while it has no proofs and its due is above
 *  the proof threshold in force on its date (its person's grade's then when one is set, else the sheet's). A sheet with no threshold then, and a claim whose due is n/a,
 *  need no proof. */
final class CheckProofs {
    private CheckProofs() {
    }

    static void refuseUnproved(StatusInput input, Claim claim, SettingStore settings, PersonStore people,
            RateStore rates, SheetStore sheets, ClaimStore claims) throws InvalidSheetException {
        ClaimStatus from = claim.getStatus();
        if (input.status() != ClaimStatus.SETTLED || (from != ClaimStatus.OPEN && from != ClaimStatus.PENDING)
                || claim.getProofs() > 0) {
            return;
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        String grade = person == null ? null : person.gradeOn(claim.getDate());
        BigDecimal threshold = settings.proofThreshold(claim.getSheetId(), grade, claim.getDate());
        if (threshold == null) {
            return;
        }
        BigDecimal pct = person == null ? null : rates.forClaim(claim).find(claim.getSheetId(), grade, claim.getDate());
        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims, people).due(claim, pct);
        if (due != null && due.compareTo(threshold) > 0) {
            throw new InvalidSheetException("A claim due above the proof threshold of " + threshold.setScale(2)
                    + " needs a proof before it can be " + (input.review() ? "approved" : "settled"));
        }
    }

    /** Refuses opening a DRAFT claim with an empty note while its due is above the note threshold in force on
     *  its date. A sheet with no threshold then, and a claim whose due is n/a, need no note. */
    static void refuseUnnoted(Claim claim, SettingStore settings, PersonStore people, RateStore rates,
            SheetStore sheets, ClaimStore claims) throws InvalidSheetException {
        if (claim.getNote() != null && !claim.getNote().isBlank()) {
            return;
        }
        BigDecimal threshold = settings.noteThreshold(claim.getSheetId(), claim.getDate());
        if (threshold == null) {
            return;
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        BigDecimal pct = person == null ? null : rates.forClaim(claim).find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims, people).due(claim, pct);
        if (due != null && due.compareTo(threshold) > 0) {
            throw new InvalidSheetException("A claim due above the note threshold of " + threshold.setScale(2)
                    + " needs a note before it can be opened");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.plugin.variable.Val;

/** Records a stored proof: CLAIM_PROOF_ADDED sheet=<id> by=<user> person=<name> amount=<0.00>
 *  date=<yyyy-mm-dd>, then number=<n> when the claim has one, then proofs=<count>. */
public class AuditClaimProof {
    public void audit(@Val ProofInput input, @Val Claim claim, PersonStore people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_PROOF_ADDED sheet=" + claim.getSheetId() + " by=" + input.user() + " person="
                + person.getName() + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.getNumber() == null ? "" : " number=" + claim.getNumber())
                + " proofs=" + claim.getProofs());
    }
}
# POST /api/sheets/{sheetId}/claims/{claimId}/proof — raise a claim's proofs count by one (body {user}).
# Refused (400) for a SETTLED or VOID claim, a claim not on the sheet, or one whose due-by falls in a
# closed period; nothing is stored then. A stored proof is recorded in the audit file as CLAIM_PROOF_ADDED.
validate:
  class: net.officefloor.hq.app.claim.ValidateProof
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyProof
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimProof
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/claims/{claimId}/status — move a claim to a new status (body
# {status, user, review, reason}): DRAFT to OPEN, OPEN to SETTLED, DRAFT, OPEN or PENDING to VOID,
# and SETTLED to VOID by a steward within 7 days of its settling (its status log's SETTLED date); DRAFT
# to DELETED (deleted: it counts nowhere), and DELETED back to DRAFT (restored) only on the sheet's today it
# was deleted on (its status log's last DELETED date).
# A clerk (any user not assigned steward) settling a claim whose due is above the sheet's clerk limit
# sends it to PENDING instead. A steward reviews a PENDING claim (review true): status SETTLED approves
# it (not by the user who opened it or last edited it), status OPEN with a reason rejects it. Refused (400) for any
# other change, when the sheet's permission matrix (perm-open, perm-settle, perm-void; by default a
# clerk or a steward) does not allow the user's role to open, settle or void, when settling or approving a claim with no proofs whose due is above the proof threshold
# in force on its date, when opening a claim with an empty note whose due is above the note threshold
# in force on its date (both checked before the clerk limit, so it never goes to PENDING), when the user who opened the claim or last edited it (claim form or amount entry) tries to settle or approve it, when the claim is not on
# the sheet, or when its due-by falls in a closed period, or when opening a DRAFT whose due-by falls in a period
# with a cap while its person already has that many OPEN or PENDING claims due in it; nothing is stored then. Opening records the
# user as the claim's opened-by; a claim whose due is above the review threshold in force on its date goes to REVIEW (no
# number yet, CLAIM_REVIEW) instead of OPEN, and only a steward's review (status OPEN, review true) moves it on: CLAIM_REVIEWED,
# then CLAIM_OPENED with its number. A REVIEW claim may otherwise only be voided.
# A stored change is recorded in the audit file as CLAIM_OPENED,
# CLAIM_PENDING, CLAIM_SETTLED, CLAIM_APPROVED, CLAIM_REJECTED, CLAIM_VOIDED, CLAIM_DELETED or CLAIM_RESTORED (with reversed=<the
# frozen figure> when a SETTLED claim is voided). While the sheet has void reasons, a void needs one of
# them as its reason (refused otherwise); it is kept on the claim and CLAIM_VOIDED ends with reason=<it>.
validate:
  class: net.officefloor.hq.app.claim.ValidateStatus
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: checkLimit
checkLimit:
  class: net.officefloor.hq.app.claim.CheckClerkLimit
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
